apply.studio_css:
/* Typography Studio · personality=calm · pair=playfair_manrope */
:root {
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Manrope", "Segoe UI", system-ui, sans-serif;
  --font-sans: "Manrope", "Segoe UI", system-ui, sans-serif;
  --type-body-lh: 1.75;
  --type-headline-lh: 1.08;
  --type-track-display: -0.03em;
  --type-track-body: 0.015em;
  --type-btn-weight: 500;
}
body {
  font-family: var(--font-body);
  font-weight: 400;
  line-height: var(--type-body-lh);
  letter-spacing: var(--type-track-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.5rem, 5.5vw, 4.1rem);
  line-height: var(--type-headline-lh);
  letter-spacing: var(--type-track-display);
}
body .section h2,
body h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.55rem, 2.6vw, 2.2rem);
  line-height: 1.2;
  letter-spacing: var(--type-track-display);
}
body .btn,
body button.btn,
body a.btn {
  font-family: var(--font-body);
  font-weight: var(--type-btn-weight);
  letter-spacing: 0.02em;
}
@media (max-width: 720px) {
  body { line-height: 1.6; }
  body .hero h1,
  body .hero .hero-title,
  body h1 {
    font-size: clamp(2rem, 8vw, 2.6rem);
    letter-spacing: -0.015em;
  }
}

